import{_ as r,o as t,c as o,a2 as e}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"基底层与现实世界","description":"","frontmatter":{},"headers":[],"relativePath":"底层/规则/基底层与现实世界.md","filePath":"底层/规则/基底层与现实世界.md","lastUpdated":null}'),l={name:"底层/规则/基底层与现实世界.md"};function n(i,a,s,h,d,p){return t(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="基底层与现实世界" tabindex="-1">基底层与现实世界 <a class="header-anchor" href="#基底层与现实世界" aria-label="Permalink to &quot;基底层与现实世界&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>基底层与现实世界是神造物世界观的最底层设定之一，描述了世界的起源、结构与基本运作原理。基底层是一切的源头，现实世界则是初代创造神在此基础上的创造物。这一设定构成了整个世界观的基础架构。</p><h2 id="基底层" tabindex="-1">基底层 <a class="header-anchor" href="#基底层" aria-label="Permalink to &quot;基底层&quot;">​</a></h2><p><strong>基底层</strong>是一切的源头，纯粹的虚无，亦是纯粹的存在。它与现实世界的关系，类似于游戏素材库与游戏本身的关系。</p><h3 id="基本特征" tabindex="-1">基本特征 <a class="header-anchor" href="#基本特征" aria-label="Permalink to &quot;基本特征&quot;">​</a></h3><ul><li><strong>包含一切</strong>：基底层包含一切现实世界所可能拥有的，并同样拥有现实世界所不可能拥有的</li><li><strong>非线性时空</strong>：其内部的空间与时间，甚至因果都是非线性，甚至不存在的</li><li><strong>不可理解性</strong>：正常的思维完全无法理解这个地方</li><li><strong>神权亘古存在</strong>：神权在此亘古存在，是所有神权、宇宙的起源载体</li></ul><p>初代创造神就是在这里创造了整个现实世界。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/初代创造神">初代创造神</a></p></blockquote><h2 id="现实世界的诞生" tabindex="-1">现实世界的诞生 <a class="header-anchor" href="#现实世界的诞生" aria-label="Permalink to &quot;现实世界的诞生&quot;">​</a></h2><p>初代创造神的起源时间尚无明确记载，其存在状态尚不明确，可能始终存在，亦可能从未存在。然而，无论出于何种目的，初代创造神确实出现并开始了创造行为，现实世界由此诞生。</p><h3 id="创造过程" tabindex="-1">创造过程 <a class="header-anchor" href="#创造过程" aria-label="Permalink to &quot;创造过程&quot;">​</a></h3><p><strong>创造过程</strong>：</p><ol><li><strong>弦的模仿</strong>：初代创造神出于未知原因，开始模仿自身——即&quot;弦&quot;的形态，从弦的基本结构开始构建了一切物质</li><li><strong>微观到宏观</strong>：初始的现实世界极为狭小，仅能容纳一些基础夸克，随后逐渐扩张到能够容纳基础原子、粒子、分子的尺度，但总体积不超过一颗篮球大小</li><li><strong>宇宙大爆炸</strong>：最终，创造神将这个小现实世界扩大了无数倍。瞬间，宇宙大爆炸发生，现实世界就此初步成型</li></ol><p>初代创造神微弱且原始的意识完全无法理解自身创造物的现状，它或许仍在进行思考，但由于其意识过于微弱且原始，思考所耗费的时间跨度过于漫长，以至于在实际层面可以忽略不计。</p><h3 id="现实世界的初衷" tabindex="-1">现实世界的初衷 <a class="header-anchor" href="#现实世界的初衷" aria-label="Permalink to &quot;现实世界的初衷&quot;">​</a></h3><p>现实世界的初衷很可能是初代创造神希望创造一个更适合自身这种有意识实体存在的空间。为此，它为现实世界制定了诸多规则，使其能够排斥基底层，独立于其之外，从而拥有稳定的时间、空间以及因果律。</p><h2 id="现实世界的封闭与薄弱点" tabindex="-1">现实世界的封闭与薄弱点 <a class="header-anchor" href="#现实世界的封闭与薄弱点" aria-label="Permalink to &quot;现实世界的封闭与薄弱点&quot;">​</a></h2><p>现实世界是由初代创造神所创造、初代变化神所完善的一个<strong>封闭世界</strong>。其在高维基底层中的结构可类比为一个三维世界中的气球表面：<strong>体积有限但没有边界</strong>，同时如同气球一样存在一个封闭口——此处最为脆弱，易被撕裂，出现裂隙，从而导致基底层侵入。</p><h3 id="封闭口位置" tabindex="-1">封闭口位置 <a class="header-anchor" href="#封闭口位置" aria-label="Permalink to &quot;封闭口位置&quot;">​</a></h3><p>这个封闭口的位置即为<strong>地球</strong>的位置——因<strong>初代变化神是人类</strong>，故将封闭口（四维闭环闭合点）定为地球位置，<strong>便于自己的继承者（奥克尔）进行监管</strong>。</p><h3 id="宇宙坐标系原点" tabindex="-1">宇宙坐标系原点 <a class="header-anchor" href="#宇宙坐标系原点" aria-label="Permalink to &quot;宇宙坐标系原点&quot;">​</a></h3><p>初代变化神将四维闭合球面的&quot;闭合点&quot;放在<strong>地球地核</strong>。这个点是宇宙空间坐标的零点，整个宇宙相对于地球而定。离地球越近，越容易在固定点上积累力量戳破现实；离地球越远（如月球），相对位移越大，越难将现实捅漏。这就是地球容易出事而其他地方相对安全的原因。</p><h3 id="初始状态与基底层渗入" tabindex="-1">初始状态与基底层渗入 <a class="header-anchor" href="#初始状态与基底层渗入" aria-label="Permalink to &quot;初始状态与基底层渗入&quot;">​</a></h3><p><strong>初始状态</strong>：宇宙大爆炸时，现实世界尚未封闭，存在边际并直接与基底层相连通。虽然有排斥作用，但由于现实世界体积膨胀，表面积增加，单位面积的排斥作用相应减小，因此基底层可以轻易从边缘渗入。</p><p><strong>变化神权侵入</strong>：现实世界尚未封闭时，变化神权从边缘渗入，寻找到了人类作为载体（此时人类处于原始社会）</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../人物/初代变化神">初代变化神</a></p></blockquote><h2 id="初代变化神的作用" tabindex="-1">初代变化神的作用 <a class="header-anchor" href="#初代变化神的作用" aria-label="Permalink to &quot;初代变化神的作用&quot;">​</a></h2><p>初代变化神伴随着人类走完了整个文明史，在此期间不断探索宇宙与自身，并探究过基底层，初步了解了神权相关知识，根据自身神权的性质对可能存在的创造神、毁灭神做出了预测。</p><h3 id="初代变化神的宏愿" tabindex="-1">初代变化神的宏愿 <a class="header-anchor" href="#初代变化神的宏愿" aria-label="Permalink to &quot;初代变化神的宏愿&quot;">​</a></h3><p>针对神权的危险性以及现实世界被基底层日益侵入的状况，初代变化神最终许下宏愿：</p><ul><li><strong>神权规则补充</strong>：制定了如神权之间互相无法影响，神权施行需要代价等神权基本规则</li><li><strong>四维闭环</strong>：将现实世界在四维空间上进行了闭环，使其变为了一个空间有限，却没有边界的世界</li><li><strong>薄弱点定位</strong>：闭环的位置（也就是薄弱点的位置）被定在了地球</li><li><strong>继任者指定</strong>：由其宏愿中指定的继任者——即第二代变化神看守</li></ul><h2 id="地脉与薄弱点" tabindex="-1">地脉与薄弱点 <a class="header-anchor" href="#地脉与薄弱点" aria-label="Permalink to &quot;地脉与薄弱点&quot;">​</a></h2><p>地球作为封闭口与薄弱点，在历史中曾因行星级破坏被撕裂，形成名为<strong>地脉</strong>的伤口现象，并衍生出地脉危机、魔法等后续设定。这些内容属于中层设定，其表象、终极源头、危机本质与魔法体系详见：</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./神权体系">神权体系</a></p></li><li><p><a href="./叙事与玩家">叙事与玩家</a></p></li><li><p><a href="./../../中层/世界/历代三神" class="layer-link" data-layer="中层">历代三神</a></p></li><li><p><a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></li><li><p><a href="./../../中层/历史/前传超算纪元" class="layer-link" data-layer="中层">前传超算纪元</a></p></li></ul><hr>',39)])])}const g=r(l,[["render",n]]);export{u as __pageData,g as default};
